<script setup lang="ts">
import { computed } from "vue";
import type { NotificationKind, NotificationPolicy } from "@papilio/api";
import NumField from "@papilio/ui/NumField.vue";
import { kinds } from "./labels";
import {useI18n} from "vue-i18n";
const {t}=useI18n();
const props=defineProps<{supportedKinds?:NotificationKind[]}>();
const visibleKinds=computed(()=>Object.fromEntries(Object.entries(kinds).filter(([kind])=>props.supportedKinds?props.supportedKinds.includes(kind as NotificationKind):!kind.startsWith("checkout_")).map(([kind])=>[kind,t(`notificationKinds.${kind}`)])) as Partial<Record<NotificationKind,string>>);
const model=defineModel<NotificationPolicy>({required:true});
function addTemplate(kind:NotificationKind):void {
 if(!visibleKinds.value[kind]||model.value.templates[kind])return;
 model.value.templates[kind]={enabled:false,title:"",body:""};
}
const sizes=[{key:"retry_seconds",label:"initial"},{key:"max_retry_seconds",label:"maximum"},{key:"max_attempts",label:"attempts"},{key:"lease_seconds",label:"lease"},{key:"max_message_chars",label:"chars"}] as const;
</script>
<template><div class="form-grid"><label class="check-row"><input v-model="model.enabled" type="checkbox" />{{t('settingsEditors.notifications.enable')}}</label><label class="check-row"><input v-model="model.delivery_enabled" type="checkbox" />{{t('settingsEditors.notifications.telegram')}}</label><label class="field"><span>{{t('settingsEditors.notifications.channel')}}</span><select v-model="model.channel_mode" :aria-label="t('settingsEditors.notifications.channel')"><option value="inbox">{{t('settingsEditors.notifications.inbox')}}</option><option value="telegram">{{t('settingsEditors.notifications.telegramOnly')}}</option><option value="both">{{t('settingsEditors.notifications.both')}}</option></select></label><label class="field"><span>{{t('settingsEditors.notifications.uncertain')}}</span><select v-model="model.ambiguous_mode" :aria-label="t('settingsEditors.notifications.uncertain')"><option value="hold">{{t('settingsEditors.notifications.hold')}}</option><option value="retry">{{t('settingsEditors.notifications.retry')}}</option></select></label><label class="field"><span>{{t('settingsEditors.notifications.delay')}}</span><select v-model="model.backoff_mode" :aria-label="t('settingsEditors.notifications.delay')"><option value="fixed">{{t('settingsEditors.notifications.fixed')}}</option><option value="exponential">{{t('settingsEditors.notifications.exponential')}}</option></select></label><NumField v-for="size in sizes" :key="size.key" :label="t(`settingsEditors.notifications.${size.label}`)" :model-value="String(model[size.key])" @update:model-value="model[size.key]=Number($event)" /><fieldset v-for="(label,key) in visibleKinds" :key="key" class="form-grid"><legend>{{label}}</legend><template v-if="model.templates[key]"><label class="check-row"><input v-model="model.templates[key].enabled" type="checkbox" />{{t('settingsEditors.notifications.enabled',{label})}}</label><label class="field"><span>{{t('settingsEditors.notifications.label',{label})}}</span><input v-model="model.templates[key].title" required /></label><label class="field"><span>{{t('settingsEditors.notifications.text',{label})}}</span><textarea v-model="model.templates[key].body" required rows="3" /></label></template><template v-else><p class="subtitle">{{t('settingsEditors.notifications.missing')}}</p><button type="button" class="btn secondary" @click="addTemplate(key)">{{t('settingsEditors.notifications.add',{label})}}</button></template></fieldset><p class="hint-box">{{t('settingsEditors.notifications.hint')}}</p></div></template>
